<template><view class="page"><text class="hero">设备管理</text><text class="sub">查看老人设备在线状态并进行基础管理</text><view v-for="d in devices" :key="d.id" class="card"><view class="top"><view><text class="name">{{d.name}}</text><text class="desc">{{d.desc}}</text></view><text class="status">{{d.online?'在线':'离线'}}</text></view><view class="meta">最近同步：{{d.last}}</view><view class="actions"><button size="mini" @tap="rename(d)">重命名</button><button size="mini" @tap="detail(d)">设备详情</button></view></view><button class="add" @tap="add">+ 添加设备</button></view></template><script>export default{data(){return{devices:[{id:1,name:'客厅守护设备',desc:'活动感知 · 紧急呼叫',online:true,last:'2分钟前'},{id:2,name:'智能手环',desc:'心率 · 步数 · 睡眠',online:true,last:'5分钟前'}]}},methods:{rename(d){uni.showModal({title:'重命名设备',editable:true,placeholderText:d.name,success:r=>{if(r.confirm&&r.content)d.name=r.content}})},detail(d){uni.showModal({title:d.name,content:d.desc+'\n状态：'+(d.online?'在线':'离线')+'\n最近同步：'+d.last,showCancel:false})},add(){uni.showActionSheet({itemList:['扫码添加','输入设备码'],success:()=>uni.showToast({title:'测试添加完成',icon:'success'})})}}}</script><style scoped>.page{min-height:100vh;padding:30rpx;background:#f6f7f3}.hero{display:block;font-size:40rpx;font-weight:900;color:#2d4338}.sub{display:block;margin:10rpx 0 28rpx;color:#7b857f;font-size:22rpx}.card{margin-bottom:18rpx;padding:26rpx;background:#fff;border-radius:26rpx}.top{display:flex;justify-content:space-between}.name,.desc{display:block}.name{font-size:27rpx;font-weight:900}.desc,.meta{margin-top:6rpx;font-size:20rpx;color:#7b857f}.status{color:#3f765a;font-size:20rpx}.actions{display:flex;gap:14rpx;margin-top:20rpx}.add{margin-top:10rpx;background:#326a53;color:#fff;border-radius:20rpx}</style>